int main() {
    string s;
    getline(cin, s);
    vector<string> tmp = split(s, " ");
    int n = tmp.size();
    vector<int> ans(n);
    map<int, int> cnts;
    for (int i = 0; i < n; i++) {
        ans[i] = stoi(tmp[i]);
        cnts[ans[i]]++;
    }
    int res = 0;
    for (auto p : cnts) {
        // 代表小区应该有的人数
        int total = p.first + 1;
        // 贪心，让拥有朋友相同的情况，尽可能处于一个小区，向上取整
        res += (ceil(p.second * 1.0 / total)) * total ; 
    } 
    cout << res;
    return 0;
​
}

