public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String[] input = scanner.nextLine().split(" ");
        scanner.close();
​
        int n = input.length;
        int[] ans = new int[n];
        Map<Integer, Integer> cnts = new HashMap<>();
​
        // 统计每个数的出现次数
        for (int i = 0; i < n; i++) {
            ans[i] = Integer.parseInt(input[i]);
            cnts.put(ans[i], cnts.getOrDefault(ans[i], 0) + 1);
        }
​
        int res = 0;
        for (Map.Entry<Integer, Integer> entry : cnts.entrySet()) {
            // 小区实际的人数
            int total = entry.getKey() + 1;
            // 贪心，尽可能让小朋友处于一个或多个小区。  Math.ceil(entry.getValue() * 1.0 / total) 最少小区的数量  
            res += Math.ceil(entry.getValue() * 1.0 / total) * total;
        }
​
        System.out.println(res);
    }
}
