rl.on("line", (line) => {
    const ans = line.trim().split(" ").map(Number);

    // 统计每个数的出现次数
    const cnts = new Map();
    ans.forEach(num => {
        cnts.set(num, (cnts.get(num) || 0) + 1);
    });
​
    let res = 0;
    cnts.forEach((value, key) => {
        // 小区实际人数
        let total = key + 1;
        // 贪心尽可能让这些小朋友分配到一个或多个小区内   Math.ceil(value / total) 最小需要的小区数量
        res += Math.ceil(value / total) * total;
    });
​
    console.log(res);
    rl.close();
});
