import (
    "bufio"
    "fmt"
    "math"
    "os"
    "strconv"
    "strings"
)
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
    scanner.Scan()
    input := strings.Split(scanner.Text(), " ")
​
    // 统计每个数的出现次数
    cnts := make(map[int]int)
    for _, s := range input {
        num, _ := strconv.Atoi(s)
        cnts[num]++
    }
​
    res := 0
    for k, v := range cnts {
        // 小区实际人数
        total := k + 1
        // 尽可能让这些小朋友处于一个或多个小区 int(math.Ceil(float64(v)/float64(total))) 需要最少的小区数量
        res += int(math.Ceil(float64(v)/float64(total))) * total
    }
​
    fmt.Println(res)
}
